<script setup lang="ts">
import AftercarePanel from '../components/AftercarePanel.vue'
import BillingPanel from '../components/BillingPanel.vue'
import { ref,onMounted,onBeforeUnmount,nextTick,watch } from 'vue'
import { useRoute } from 'vue-router'
import { Search,RefreshCw,ArrowUpRight,ChevronRight,ClipboardList,Clock3,CheckCircle2,AlertTriangle } from 'lucide-vue-next'
import { ElMessage,ElMessageBox } from 'element-plus'
import * as echarts from 'echarts/core'
import { BarChart } from 'echarts/charts'
import { GridComponent,TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
echarts.use([BarChart,GridComponent,TooltipComponent,CanvasRenderer])
import { get,post,key,statusNames,priorityNames,date } from '../api'
const route=useRoute()
const rows=ref<any[]>([]),stats=ref<any>({}),busy=ref(false),total=ref(0),page=ref(1),status=ref(''),search=ref(''),selected=ref<any>(null),drawer=ref(false),logs=ref<any[]>([]),records=ref<any[]>([]),pictures=ref<any[]>([]),candidates=ref<any[]>([]),acting=ref(false),assignOpen=ref(false),workerId=ref(''),manual=ref<any[]>([]),chartNode=ref<HTMLDivElement>(),chart: {value:echarts.ECharts|undefined}={value:undefined}
const phases=[['SUBMITTED','审核'],['PENDING_DISPATCH','派单'],['ASSIGNED','接单'],['IN_PROGRESS','维修'],['PENDING_CONFIRM','验收'],['CLOSED','完成']]
async function load(){busy.value=true;try{const [orders,overview]=await Promise.all([get('/repair/orders',{page:page.value,size:10,status:status.value,search:search.value}),get('/statistics/overview')]);rows.value=orders.records;total.value=orders.total;stats.value=overview;await nextTick();renderChart()}finally{busy.value=false}}
function renderChart(){if(!chartNode.value)return;if(!chart.value)chart.value=echarts.init(chartNode.value);chart.value.setOption({color:['#0b7774'],tooltip:{trigger:'axis'},grid:{top:16,right:12,bottom:24,left:28},xAxis:{type:'category',data:stats.value.trend?.map((t:any)=>String(t.day).slice(5))??[],axisLine:{lineStyle:{color:'#dfe8ea'}},axisLabel:{color:'#7b8d92'},axisTick:{show:false}},yAxis:{type:'value',minInterval:1,splitNumber:2,splitLine:{lineStyle:{color:'#edf1f2'}},axisLabel:{color:'#7b8d92',fontSize:9}},series:[{type:'bar',barMaxWidth:24,itemStyle:{borderRadius:[4,4,0,0]},data:stats.value.trend?.map((t:any)=>Number(t.count))??[]}]})}
async function detail(order:any){selected.value=await get(`/repair/orders/${order.id}`);drawer.value=true;candidates.value=[];const [a,b,media]=await Promise.all([get(`/repair/orders/${order.id}/logs`),get(`/repair/orders/${order.id}/work-records`),get(`/repair/orders/${order.id}/media`)]);logs.value=a;records.value=b;pictures.value=await Promise.all(media.map(async(m:any)=>({...m,...await get(`/files/${m.fileId}/access-url`)})))}
async function action(name:string,extra:any={}){if(!selected.value)return;acting.value=true;try{await post(`/repair/orders/${selected.value.id}/${name}`,{version:selected.value.version,...extra},key());ElMessage.success('工单已更新');await detail(selected.value);await load()}catch(error){await detail(selected.value)}finally{acting.value=false}}
async function reasonAction(name:string){try{const result=await ElMessageBox.prompt('请填写原因，记录将保留在工单时间线中',name==='review'?'驳回报修':'撤回派单',{inputValidator:v=>!!v?.trim()||'请填写原因',confirmButtonText:'确认',cancelButtonText:'取消'});await action(name,{reason:result.value,approved:false})}catch{}}
async function openAssign(){assignOpen.value=true;workerId.value='';candidates.value=[];manual.value=await get('/workers',{communityId:selected.value.communityId});try{candidates.value=await post(`/repair/orders/${selected.value.id}/recommendations`)}catch{}}
async function assign(){if(!workerId.value){ElMessage.warning('请选择维修人员');return}if(selected.value.facilityScope==='PUBLIC'){try{await ElMessageBox.confirm('请核实这是公共设施维修，本次居民无需支付。归属有误请取消并先更正。','确认公共设施归属')}catch{return}}const candidate=candidates.value.find(c=>c.workerId===workerId.value);await action('assign',{confirmedFacilityScope:selected.value.facilityScope,workerId:workerId.value,dispatchType:candidate?'SMART':'MANUAL',recommendationId:candidate?.recommendationId});assignOpen.value=false}
function resize(){chart.value?.resize()}
onMounted(async()=>{window.addEventListener('resize',resize);await load();const orderId=route.query.orderId;if(typeof orderId==='string'&&/^\d+$/.test(orderId))await detail({id:orderId})});onBeforeUnmount(()=>{chart.value?.dispose();window.removeEventListener('resize',resize)})
</script>
<template>
<div class="page-heading"><div><span class="eyebrow">社区服务 · 日常调度</span><h1>报修工作台</h1><p class="muted">把待办接稳，让服务顺畅流转。</p></div><button class="secondary-button" @click="load" :disabled="busy"><RefreshCw :size="16"/>刷新数据</button></div>
<section class="overview-grid"><div class="metric"><span><ClipboardList :size="17"/>本月报修</span><strong>{{stats.newOrders??'—'}}</strong><small>本月新提交工单</small></div><div class="metric"><span><Clock3 :size="17"/>当前待处理</span><strong>{{stats.pendingOrders??'—'}}</strong><small>等待服务的工单</small></div><div class="metric"><span><CheckCircle2 :size="17"/>本月已完成</span><strong>{{stats.closedOrders??'—'}}</strong><small>居民已确认验收</small></div><div class="metric"><span><AlertTriangle :size="17"/>本月超时</span><strong class="warning">{{stats.overdueOrders??'—'}}</strong><small>需要关注的服务</small></div></section>
<section class="activity-strip"><div><span class="eyebrow">服务接力</span><div class="phase-path"><button v-for="phase in phases" :key="phase[0]" @click="status=phase[0];page=1;load()" :class="{active:status===phase[0]}"><span></span>{{phase[1]}}<ChevronRight :size="14"/></button></div><p>从审核到验收，每一步都有记录。</p></div><div class="trend"><span>本月报修趋势</span><div ref="chartNode" class="trend-chart"></div><small v-if="!stats.trend?.length">暂无报修数据</small></div></section>
<section class="panel"><div class="panel-toolbar"><div class="panel-title"><h2>社区工单</h2><span>{{total}} 条</span></div><div class="filters"><el-input v-model="search" clearable placeholder="搜索编号或报修标题" @keyup.enter="page=1;load()" @clear="load"><template #prefix><Search :size="16"/></template></el-input><el-select v-model="status" clearable placeholder="全部状态" @change="page=1;load()"><el-option v-for="(label,value) in statusNames" :key="value" :label="label" :value="value"/></el-select><el-button @click="page=1;load()">查询</el-button></div></div>
<el-table :data="rows" v-loading="busy" @row-click="detail" class="orders-table" empty-text="暂无工单，居民提交报修后会显示在这里"><el-table-column label="报修事项" min-width="250"><template #default="{row}"><div class="order-title">{{row.title}}</div><div class="subline">{{row.orderNo}} <span>· {{row.categoryName}}</span></div></template></el-table-column><el-table-column label="报修位置" min-width="170"><template #default="{row}">{{row.communityName}}<div class="subline">{{row.facilityScope==='PUBLIC'?row.locationText:`${row.buildingNo}栋 ${row.unitNo}单元 ${row.roomNo}室`}}</div></template></el-table-column><el-table-column label="优先级" width="90"><template #default="{row}"><span class="priority" :class="row.priority">{{priorityNames[row.priority]}}</span></template></el-table-column><el-table-column label="服务进度" width="110"><template #default="{row}"><span class="state-pill" :class="row.status">{{statusNames[row.status]}}</span></template></el-table-column><el-table-column label="负责人" width="100"><template #default="{row}">{{row.workerName??'待分配'}}</template></el-table-column><el-table-column label="提交时间" width="140"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column width="48"><template #default><ArrowUpRight :size="18"/></template></el-table-column></el-table>
<div class="pagination"><span>显示第 {{page}} 页</span><el-pagination v-model:current-page="page" :page-size="10" :total="total" layout="prev,pager,next" @current-change="load"/></div></section>
<el-drawer v-model="drawer" size="min(650px, 100vw)" title="工单详情"><template v-if="selected"><div class="drawer-title"><span class="state-pill" :class="selected.status">{{statusNames[selected.status]}}</span><span class="priority" :class="selected.priority">{{priorityNames[selected.priority]}}</span><h2>{{selected.title}}</h2><p class="subline">{{selected.orderNo}} · 第 {{selected.roundNo}} 轮维修</p></div><div class="detail-address">{{selected.communityName}} · {{selected.facilityScope==='PUBLIC'?selected.locationText:`${selected.buildingNo}栋${selected.unitNo}单元${selected.roomNo}室`}}</div><p class="description">{{selected.description}}</p><div class="photo-grid"><a v-for="photo in pictures" :key="photo.id" :href="photo.url" target="_blank" rel="noreferrer"><img :src="photo.url" :alt="photo.type==='FAULT'?'故障图片':'维修结果图片'"/></a></div><div class="detail-pairs"><span>报修居民<strong>{{selected.residentName}}</strong></span><span>维修人员<strong>{{selected.workerName??'待分配'}}</strong></span><span>提交时间<strong>{{date(selected.createdAt)}}</strong></span><span>响应截止<strong>{{date(selected.responseDeadlineAt)}}</strong></span></div><BillingPanel :order="selected" @updated="detail(selected)"/><AftercarePanel v-if="selected.status==='CLOSED'" :order="selected"/><div class="action-row"><el-button v-if="selected.status==='SUBMITTED'" type="primary" :loading="acting" @click="action('review',{approved:true})">确认归属并审核通过</el-button><el-button v-if="selected.status==='SUBMITTED'" @click="reasonAction('review')">驳回报修</el-button><el-button v-if="selected.status==='PENDING_DISPATCH'" type="primary" @click="openAssign">分配维修人员</el-button><el-button v-if="['ASSIGNED','ACCEPTED'].includes(selected.status)" @click="reasonAction('revoke')">撤回派单</el-button></div><h3 class="detail-section-title">维修记录</h3><p v-if="!records.length" class="muted">维修人员处理后，记录将显示在这里</p><div v-for="record in records" :key="record.id" class="work-record"><span class="subline">第{{record.roundNo}}轮 · {{date(record.createdAt)}}</span><p>{{record.content}}</p></div><h3 class="detail-section-title">进度时间线</h3><el-timeline><el-timeline-item v-for="entry in [...logs].reverse()" :key="entry.id" :timestamp="date(entry.createdAt)" color="#0b7774"><strong>{{statusNames[entry.newStatus]}}</strong><p v-if="entry.remark">{{entry.remark}}</p></el-timeline-item></el-timeline></template></el-drawer>
<el-dialog v-model="assignOpen" title="分配维修人员" width="min(560px, 95vw)"><p class="muted">根据技能、服务区域、当前负载与评价推荐</p><div v-if="candidates.length" class="candidate-list"><button v-for="candidate in candidates" :key="candidate.workerId" :class="{selected:workerId===candidate.workerId}" @click="workerId=candidate.workerId"><span class="avatar">{{candidate.name?.slice(0,1)}}</span><span><strong>{{candidate.name}}</strong><small>{{candidate.reason}}</small></span><b>{{Number(candidate.score).toFixed(1)}}<small>适配分</small></b></button></div><p v-else class="muted">暂无推荐候选，可检查服务范围、技能与人员容量</p><el-select v-model="workerId" placeholder="人工选择维修人员" class="full"><el-option v-for="worker in manual" :key="worker.id" :value="worker.id" :label="`${worker.realName} · ${worker.workStatus==='AVAILABLE'?'可接单':'不可用'}`" :disabled="worker.workStatus!=='AVAILABLE'"/></el-select><template #footer><el-button @click="assignOpen=false">取消</el-button><el-button type="primary" :loading="acting" @click="assign">确认派单</el-button></template></el-dialog>
</template>
